import{_ as t,a as r}from"./chunks/c72f5cb90d855a3687aa.BgwXDhid.js";import{_ as o,C as i,o as l,c as s,j as e,a as n,E as h,a5 as c}from"./chunks/framework.DNkHA0lr.js";const g=JSON.parse('{"title":"别再“自动驾驶”般虚度人生（改变未来的 4 种方法）","description":"","frontmatter":{"title":"别再“自动驾驶”般虚度人生（改变未来的 4 种方法）","originalTitle":"Stop Wasting Your Life On Autopilot (4 Ways To Change Your Future)","date":"2024-01-26","originalUrl":"https://thedankoe.com/letters/society-is-a-behavior-system-how-to-escape-the-matrix/","minutes":14,"sourceHash":"222aa0f1ba757d0cc975bcd175e5332413661f485906c207b6e1b75a59fd633b","translation":"AI-assisted, block-aligned; not official","head":[["link",{"rel":"canonical","href":"https://thedankoe.com/letters/society-is-a-behavior-system-how-to-escape-the-matrix/"}]]},"headers":[],"relativePath":"letters/society-is-a-behavior-system-how-to-escape-the-matrix.md","filePath":"letters/society-is-a-behavior-system-how-to-escape-the-matrix.md"}'),u={name:"letters/society-is-a-behavior-system-how-to-escape-the-matrix.md"};function d(m,p,b,f,k,_){const a=i("ArticleMeta");return l(),s("div",null,[p[0]||(p[0]=e("h1",{id:"别再-自动驾驶-般虚度人生-改变未来的-4-种方法",tabindex:"-1"},[n("别再“自动驾驶”般虚度人生（改变未来的 4 种方法） "),e("a",{class:"header-anchor",href:"#别再-自动驾驶-般虚度人生-改变未来的-4-种方法","aria-label":'Permalink to "别再“自动驾驶”般虚度人生（改变未来的 4 种方法）"'},"​")],-1)),h(a),p[1]||(p[1]=c('<p><a href="https://www.youtube.com/embed/xG708Y2q0qQ?feature=oembed" target="_blank" rel="noreferrer">观看原文视频</a></p><p><img src="'+t+'" alt=""></p><p>你的心智是一套复杂的系统，随着时间的推移，它在实现其所采纳的目标时会变得越来越高效。</p><p>你的心智是诠释现实的容器。</p><p>当你出生时，你的心智几乎是一张白纸。</p><p>你有生存的生物学目标，所以当你饥饿、想要引起注意、以及在尿布里拉了一泡感到不适时，你的心智会激活突触让你哭泣。大多数婴儿从子宫里出来时都在哭，因为他们刚进入了一场充满巨大刺激和未知的、名为“生命”的游戏。</p><p>随着你的成长，你开始发展出一个动觉（kinesthetic）版本的自己。</p><p>即使你看不到自己的脸，你的父母也会唱着儿歌，指着他们身体的部位来帮助你认识自己。</p><p>“眼睛、耳朵、嘴巴和鼻子。”</p><p>不久之后，你开始爬行，玩你所在文化里的玩具，走路，并试图弄懂你父母所说的这种外语。</p><p>你想要生存。你想要融入。你的心智就是一台模式识别机器。当你在潜意识中用社会的准则去尝试、失败并最终成功时，行为和语言的系统就被编程进了你的心智中。</p><p>系统是实现目标的过程，而社会系统被注入到你的心智中，这样你从小就不会失去理智。</p><p>我在新出版的书 <a href="https://theartoffocusbook.com/" target="_blank" rel="noreferrer">The Art of Focus</a>（专注的艺术）中讨论了所有这些内容。</p><h3 id="从沉睡到觉醒" tabindex="-1">从沉睡到觉醒 <a class="header-anchor" href="#从沉睡到觉醒" aria-label="Permalink to &quot;从沉睡到觉醒&quot;">​</a></h3><p>到了 30 岁时，普通人通常都身处自己建造的牢笼之中。</p><p>不是社会建造的，而是他们自己。</p><p>是你自己没有去质疑社会投射在你身上的限制。</p><p>你毫不挣扎地接受了它们。</p><p>大多数人长大后，日复一日地过着同样单调的生活，用借口、辩解和身份认同来强化他们狭隘的心智。</p><blockquote><p>动辄被冒犯。责怪除了自己以外的任何人。将你的自我价值与激进的意识形态绑定。接受一切表面现象，不质疑任何事。期望仅仅因为自己的存在就能得到免费施舍，不付出任何努力。权威告诉你做什么，你就做什么。去上学，找份工作，在某个特定的成熟年龄退休——没有任何保障——拿着刚好能撑到死的那点微薄存款。 ——《专注的艺术》</p></blockquote><p>每个年轻人的生命中都有一个转折点。</p><p>你要么继续做你脑海中那些代码的奴隶，要么经历学习它、解构它并重新编程的痛苦过程。</p><p>人们普遍认同道德发展的 3 个主要阶段：</p><ul><li><strong>前习俗水平（Pre-conventional）</strong> —— 一个尚未社会化的幼年人类，他们通过服从以避免惩罚，并出于自身利益采取行动。</li><li><strong>习俗水平（Conventional）</strong> —— 人类从自身和他人身上学习，通过顺应社会形成信念、价值观和标准。他们试图维持社会秩序。</li><li><strong>后习俗水平（Post-conventional）</strong> —— 人类对社会提出质疑和反思，从更高的层面进行观察，然后能够用批判性思维去批评或改革社会。普适原则开始发挥作用，从而得出“啊！佛教徒是对的！”这种顿悟。</li></ul><p>危险在于被困在前几个阶段。</p><p>人们在这些阶段依附于意识形态，并宣扬那种世界观是“正确的”，而其他人的都是“错误的”。</p><p>你可以在那些对虚构的上帝卑躬屈膝以避免惩罚的狂热信徒（bible thumpers）身上看到这一点。</p><p>你也可以在那些认为某种模式或做事方式是绝对正确的商人身上看到这一点。</p><p>稍微打破一下哲学的探讨——那些在创作者（creator）发展中达到后习俗水平的人会意识到，<a href="/letters/the-anti-niche-why-being-nicheless-makes-you-irreplaceable">你就是细分领域</a>（niche），并根据普适原则来经营他们的业务。</p><p>这封信将作为一个催化剂，唤醒一些充满好奇心的人。</p><h2 id="矩阵-the-matrix-是一个观念之网" tabindex="-1">矩阵（The Matrix）是一个观念之网 <a class="header-anchor" href="#矩阵-the-matrix-是一个观念之网" aria-label="Permalink to &quot;矩阵（The Matrix）是一个观念之网&quot;">​</a></h2><blockquote><p>文化是一种集体幻觉，当你走出这种集体幻觉时，你就会看清它的本来面目。 —— 泰伦斯·麦肯纳（Terrence McKenna）</p></blockquote><p>你怎么知道关于现实的任何事情？</p><p>你怎么知道什么是真，什么是假？</p><p>你怎么知道你该做什么，不该做什么？</p><p><em>你是被社会里另一个在社会中学习的人告知的。</em></p><p>你所知道的 99% 的东西都不是通过你自己的测试或实验发现的。</p><p>其他人从哪里获取信息？其他的人。</p><p><em>你得到的每一条信息都来自其他在出生时一无所知的人。</em></p><p>在你学会走路和说话之后，作为孩子你采取的下一步就是去上学，所以让我们以此为例。</p><p>教育委员会决定学校应该教什么。但是父母对教育委员会有很大的影响。父母是从哪里得到学校应该教什么或不该教什么的概念的？从他们受过的教育和他们的父母那里。</p><p>当你在公立学校不断升学时，你从其他学生和老师那里养成习惯、规范行为并发展语言。而学生和老师又是从哪里学到他们的习惯、行为和语言的？</p><p>到此时，你几乎是一个走进正规教育体系的克隆人。</p><p>让我们稍微快点过一遍这个逻辑……</p><p>大学里的学生和教育者都来自学校。在学校里教孩子的人来自大学。教导那些在大学里教书的人也来自大学。你能看出这是多么毫无根据且陷入循环的吗？</p><p>社会通过科学期刊和出版物来确定信息是否真实。想要发表，你必须顺应出版物的偏见。是谁创办了这些出版物？是那些其偏见在博士教育过程中形成的人，而教导他们的人也是受过博士教育的。</p><p>当你在学校时，你是怎么完成作业的？你会去维基百科这样的网站查资料，而上面的文章都来自大学。你又通过像谷歌这样的搜索引擎找到维基百科的页面。</p><p>谷歌根据提供什么内容最赚钱或最受欢迎来决定显示什么。谷歌根据链接和链接的权威性来赋予页面权重。谷歌对来自大学的链接赋予更高的权重。</p><p>学校系统只是这其中的一个例子。</p><p>制药公司为大学的庞大部门提供资金。</p><p>银行系统是社会中各个支柱之间运转的润滑剂。</p><p>你必须申请学生贷款来支付你的教育费用。</p><p>金钱是这个矩阵的命脉，如果金钱停止流向任何特定的领域，该领域就会像你的手失去血液供应一样死掉。</p><p>社会的结构依赖其自身而存在。</p><p>有些人可能会把这称为传销（庞氏骗局）。</p><h2 id="注意力锚点-——-负反馈制约你的心智" tabindex="-1">注意力锚点 —— 负反馈制约你的心智 <a class="header-anchor" href="#注意力锚点-——-负反馈制约你的心智" aria-label="Permalink to &quot;注意力锚点 —— 负反馈制约你的心智&quot;">​</a></h2><blockquote><p>如果你愿意，你可以生与死都在这些心智结构之中。但充满好奇心的人……通常会发现自己对那些传统的答案并不满意。 —— 泰伦斯·麦肯纳</p></blockquote><p>社会是一张由观念组成的网，它让你的心智能够理解这个世界而不至于发疯。</p><p>从这个意义上说，观念是心智能够理解并贴上标签的任何东西。观念就是一切。如果我们想疯狂一点的话，一切事物都只是现实心智中的一个观念。现实是心智层面的。</p><p>观念是完整的个体。它们层层叠加。它们让彼此得以存在。它们具有等级结构。</p><p>就像从字到句、到段落、到章节，再到一本书；而那本书也是书架整体的一部分，书架又被拆解为木头等部分，木头来自树木，而树木深深连接到生态系统中，让许多其他事物得以存在。</p><p>这个社会之网包含了诸如学校教育、媒体、经济、政府和文化等锚点，这些全都是由身处其中的人们虚构出来的。</p><p>社会是一个反馈系统，它惩罚那些不合群的人，并以此作为负反馈机制，为了社会的目标去纠正人的行为。</p><p>当孩子不遵守矩阵的规则时，父母就会责骂他们。</p><p>老师用打低分的方式来鼓励死记硬背和服从。</p><p>当你做了些不合常规的事情时，同龄人会嘲笑你。</p><p>社会是一个系统。</p><p>你的心智是一个系统。</p><p>你的身份认同是一个系统。</p><p>从宏观到微观，现实是一个复杂的系统嵌套 —— 或是层级结构。现实就是一个巨大的心智。</p><p>自下而上地看，你的身份认同是由社会编程和塑造的，除非你做出有意识的选择去重新编程它。</p><p>编程就类似于条件反射或训练。</p><p>随着时间的推移和不断的重复，你养成了习惯，学会了你的语言，并形成了一种可能与你理想生活方式一致或不一致的世界观。系统在你的心智中层层叠加，形成了一张与社会深度互联的网。</p><p>这一切都始于注意力。</p><p>你的心智渴望秩序、安全感和确定性。社会提供了这些。所以你的注意力几乎是被迫集中在社会为你铺设的系统上。</p><p>你的身份认同容纳了你试图实现的显意识或潜意识的目标。</p><p>如果你是一个在社会中运行的程序，一个 NPC，并且你的目标是获得一份高薪工作，那么你的心智就不会认为创业有多重要。</p><p>表面上看这似乎没什么害处，因为“不是每个人都需要创业”，但其实际影响远比这要深远得多。</p><h3 id="解构游戏" tabindex="-1">解构游戏 <a class="header-anchor" href="#解构游戏" aria-label="Permalink to &quot;解构游戏&quot;">​</a></h3><p><img src="'+r+'" alt=""></p><p>游戏很好玩，但仅限于玩一会儿。</p><p>如果你不继续追求升级所需的挑战，它就会变得无聊。</p><p>如果你尝试玩一个新游戏却不是从第一关开始，你会感到焦虑并放弃。</p><p>游戏是一个系统。游戏是一个故事。它模仿了现实的起伏跌宕。</p><p>心智喜欢游戏，因为心智喜欢秩序。它喜欢事物合乎逻辑，讨厌事物毫无头绪。</p><p>游戏包含一套目标层级，它能够理顺心智，从而带来专注、心流（flow）和满足感 —— 但前提是你得在游戏中不断取得进展。</p><p>社会就是一场游戏，其自下而上的目标是：</p><ul><li>去上学，这样你就能和其他所有人处于同一无形的频道</li><li>找份工作，这样你就能为社会的运转做贡献</li><li>根据虚构的文化道德准则与某人结婚</li><li>被那些你根本不在乎的责任所束缚（只因为社会要求你这样做）</li><li>被迫把注意力集中在鸡毛蒜皮的问题上，以此浪费你的时间，让你永远不会因为追求自己的事业和自由思考而对社会构成威胁</li><li>在能够退休的年纪拿着一点积蓄退休，一切就如一直计划好的那样</li><li>指望再也不用工作，并进入永远的假期（我们都知道最后会变成什么样）</li></ul><p>在学校时，生活在某种程度上还算吸引人，但当你接到社会游戏里找工作的任务时，无聊感会慢慢侵蚀你的理智，把你变成一个只知寻欢作乐的机器人。</p><p>这就是 99% 的人的结局。</p><p>如果你不创造自己的游戏，你就会被困在别人的游戏里，那会变得很无聊……把你送入一个充满压力且心胸狭窄的无尽循环。</p><h2 id="如何逃离矩阵" tabindex="-1">如何逃离矩阵 <a class="header-anchor" href="#如何逃离矩阵" aria-label="Permalink to &quot;如何逃离矩阵&quot;">​</a></h2><p>我写这篇文章并不是为了把社会描绘成邪恶的化身。</p><p>这主要是一个无意识的生存过程。</p><p>这是一场我们不得不玩的必要游戏，直到更多人觉醒，为后代创造出一场更具意识的游戏，这可能需要几十年甚至几个世纪的时间。</p><p>然而，对于正在阅读本文的人来说，你可以采取一些通用步骤来逃离这个矩阵。</p><p>这不是什么速成法。</p><p>这是一种生活方式。</p><p>这是你一生的事业：</p><p>去看看你究竟能做到什么地步。</p><h3 id="_1-掌控你的生存并找到目标" tabindex="-1">1) 掌控你的生存并找到目标 <a class="header-anchor" href="#_1-掌控你的生存并找到目标" aria-label="Permalink to &quot;1) 掌控你的生存并找到目标&quot;">​</a></h3><blockquote><p>你的问题是一张紧密的网，将你死死困在当前的处境中。问题从来不会孤立存在。——《专注的艺术》（The Art of Focus）</p></blockquote><p>你处于一个自己不喜欢的生活境地，是有原因的。</p><p>你未能察觉到那些把你困在那里的问题。</p><p>你没有拓宽思维去超越这些问题，去获取解决它们所需的东西（知识和技能），也没有通过解决它们来巩固那种新的思维层次。</p><p>你感到迷茫，因为你没有目标。</p><p>简单来说，你的目标就是你为了实现某个目的而正在解决的问题。大多数人被分配了一个永远不会进化的目标，他们永远被困在一种狭隘的压力状态中，被迫向着社会设定的目标前行。</p><p>当你掌控了自己的生存，你就不必再时刻担忧。</p><p>你为创造力、灵性和有意义的工作腾出了空间。</p><p>你不关心这些事，是因为你无暇顾及它们。</p><p>你还没有解决那些摆在你面前的问题。</p><p>你超重了吗？你的饮食习惯很糟糕吗？你讨厌你的工作吗？你在忽视你的人际关系吗？</p><p>这些都是相互关联的问题，而非单一存在的。</p><p>你的工作可能占据了你一天中太多的时间，以至于你没有精力去投入到生活的其他方面。你的营养状况可能导致了这种精力匮乏，并进一步波及你的人际关系。</p><p>掌控你的生存就是掌控永恒的市场：健康、财富和人际关系。</p><p>这些恰好是商业中最赚钱的垂直领域，绝非巧合。每个人都有这些问题，通过解决它们，你就能积累经验，将这些经验变现，并去做你热爱的事情。</p><p>我在<a href="/letters/the-self-reliant-career-path-how-to-generate-independent-income">《解决你自己的问题并出售解决方案》</a>一文中讨论过这一点。</p><p>只有当你实现了自我提升的那些小目标时，你才能发现更深层、更有意义的目标。</p><p>当你连自己的问题都还没解决时，别再妄图去解决世界的问题了。</p><h3 id="_2-从去中心化的学校系统中学习" tabindex="-1">2) 从去中心化的学校系统中学习 <a class="header-anchor" href="#_2-从去中心化的学校系统中学习" aria-label="Permalink to &quot;2) 从去中心化的学校系统中学习&quot;">​</a></h3><p>你没有意识到自己的潜力，因为你还没有接触过它。</p><p>你没有接触过它，是因为你所处的环境是完全已知的。</p><p>未知才是充满可能性的乐土。</p><p>你必须让自己接触新的职业路径、健康范式和社交圈。</p><p>认清你为了改变生活必须获取的知识和技能。写作、营销、销售、健身、营养学、沟通技巧等等。</p><p>一个很好的起点是 <a href="https://2hourwriter.com/" target="_blank" rel="noreferrer">2 Hour Writer</a>，因为写作是你学习任何其他技能的基础。</p><p>当你这样做时，你会感到不舒服。你的身份认同会受到威胁。这也是需要时间去积累的。</p><p>创作者经济就是那个去中心化的学校系统。</p><p>创作者们正在解决他们自己的问题，开辟新的道路，创造新的工作，并通过内容传授他们学到的东西。</p><ul><li>打破你的舒适圈</li><li>关注那些传播能改变人生的信息的新人</li><li>为了非传统的结果去投资非传统的教育</li><li>发掘你生活的新潜力并付诸行动</li></ul><p>在已知的边缘，生活才变得有意义。</p><p>当你发现新奇的信息时，你的大脑会发出信号，告诉你遇到了一件有意义的事情。</p><p>不要忽视这一点。</p><p>全力去追求它。</p><p>沉迷于教育的兔子洞。</p><p>这就是你如何敞开思维、理顺思维并训练思维，从而获得一种全新思维的方式——一种不受社会限制的思维。</p><h3 id="创造你自己的无限游戏" tabindex="-1">创造你自己的无限游戏 <a class="header-anchor" href="#创造你自己的无限游戏" aria-label="Permalink to &quot;创造你自己的无限游戏&quot;">​</a></h3><blockquote><p>创业是长期主义者唯一合乎逻辑的选择。——《专注的艺术》</p></blockquote><p>如果你想停止玩社会的游戏，你必须创造你自己的游戏。</p><p>一个有着无限进步和演化的游戏。</p><p>而不是那种把你困在特定层级、让生活变得索然无味的游戏。</p><p>要做到这一点，你需要为未来培育一个愿景，迭代一份创造那种现实的计划，并选择一个能让你实现这一切的载体。</p><p>请注意，我说的是“培育”愿景和“迭代”计划。</p><p>这是一个持续的过程。它没有终点。你的愿景不会一成不变，你的计划也不会。就像生活中的万事万物一样，它们都会改变。</p><ul><li>描绘你未来想要的一切</li><li>描绘你未来不想要的一切</li><li>建立一个目标层级来实现它</li><li>获取必要的知识和技能</li><li>以经验作为反馈机制来修改你的计划</li></ul><p>你可以在一本空白笔记本上做这些事，或者使用我专为此过程设计的 <a href="https://thedankoe.store/products/the-foci-planner" target="_blank" rel="noreferrer">FOCI 计划本</a>。</p><p>当你感到无聊时，不要放弃，转型。去追求能利用你已获技能的更高阶挑战。</p><p>举个例子：如果你对自由职业感到无聊，试试电子商务。这不是闪亮物体综合症，这是智慧。</p><p>当你感到焦虑时，在你和你试图实现的那个令人不知所措的目标之间，设定一个更清晰的阶段性目标。</p><h3 id="利用数字社会的杠杆" tabindex="-1">利用数字社会的杠杆 <a class="header-anchor" href="#利用数字社会的杠杆" aria-label="Permalink to &quot;利用数字社会的杠杆&quot;">​</a></h3><p>我把工作看作是垫脚石，而不是死刑判决（尽管对<em>很多人</em>来说，它确实是）。</p><p>对大多数人来说，直接创业是行不通的。</p><p>出于矩阵的本质，人们在生命早期就会承担起将自己束缚住的责任。</p><p>账单、家庭、房子，还有一份会榨干你所有精力、让你对此无能为力的工作。</p><p>别误会，我并不反感工作。</p><p>工作对于培养有价值的技能组合非常有用，但它们所提供的充满成就感的挑战可能会很快消退。如果工作消耗了你 1/3 的人生，却又榨干了你另外 1/3 人生的精力，而剩下的 1/3 你又在睡觉……那么这就是第一个需要改变的事情。</p><p>互联网和社交媒体已经创造了一个数字社会。</p><p>创作者和品牌是新的教育系统、媒体、政府（在这个在线空间里……人们互相揭发之类以保持空间清洁）、宗教（每个人都在推销一种意识形态）以及经济体系（每个人都在卖东西……不，这不是坏事，这是生存）。</p><p>这个社会是去中心化的。你不会被迫走上任何一条特定的路。你有选择追求你想要的东西的权利，如果你被困在原地，你应该为自己缺乏批判性思考负责。</p><p>我的建议是：</p><ul><li>利用你的技能组合，在互联网上找一份创作者或品牌旗下的工作</li><li>选择一份能给你空闲时间去追求自己事业的工作</li><li>运用你学到的新技能去打造你自己的事业</li></ul><p>你的个人资料就是你的公开简历。</p><p>我们在 <a href="https://university.kortex.co/" target="_blank" rel="noreferrer">Kortex University</a> 里教授所有这些内容，帮助你在90天内开启你的数字职业生涯。</p><p>你通过写内容来展示你的价值。你通过建立人脉来融入一个社区。你将那个社区作为杠杆来获取机会。最终，你利用获得的资源（比如受众）来建立自己的企业，过上自由的生活。</p><p>你不可能在一瞬间做到这一点，就像你花去了18年以上的时间才成为社会中的一行代码一样。</p><p>解构你正在玩的游戏。</p><p>理解在你大脑中运行的代码。</p><p>创造你自己的游戏。</p><p>享受你这周余下的时光。</p><p>Dan</p><hr><p><a href="/en/letters/society-is-a-behavior-system-how-to-escape-the-matrix">查看英文存档</a> · <a href="/letters/">返回全部文章</a></p>',172))])}const y=o(u,[["render",d]]);export{g as __pageData,y as default};
